(function () {
  'use strict';
  const COLS = 80, ROWS = 60;
  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');
  const cellW = canvas.width / COLS, cellH = canvas.height / ROWS;

  let grid = new Array(ROWS);
  let next = new Array(ROWS);
  let gen = 0, running = false, timer = null;
  let tool = 'draw';
  let cellColor = '#34d399';
  let panX = 0, panY = 0, dragging = false, drawState = null;

  function fresh() {
    for (let r = 0; r < ROWS; r++) {
      grid[r] = new Array(COLS).fill(0);
      next[r] = new Array(COLS).fill(0);
    }
  }
  fresh();

  // ---- Rendering ----
  function draw() {
    ctx.fillStyle = '#0a0c10';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // grid lines
    ctx.strokeStyle = 'rgba(255,255,255,0.05)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let c = 0; c <= COLS; c++) {
      ctx.moveTo(c * cellW, 0); ctx.lineTo(c * cellW, canvas.height);
    }
    for (let r = 0; r <= ROWS; r++) {
      ctx.moveTo(0, r * cellH); ctx.lineTo(canvas.width, r * cellH);
    }
    ctx.stroke();

    // living cells
    ctx.fillStyle = cellColor;
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (grid[r][c]) {
          ctx.fillRect(c * cellW + 1, r * cellH + 1, cellW - 2, cellH - 2);
        }
      }
    }
  }

  // ---- Simulation ----
  function liveNeighbors(r, c) {
    let n = 0;
    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr === 0 && dc === 0) continue;
        const rr = r + dr, cc = c + dc;
        if (rr >= 0 && rr < ROWS && cc >= 0 && cc < COLS) n += grid[rr][cc];
      }
    }
    return n;
  }

  function step() {
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const n = liveNeighbors(r, c);
        next[r][c] = grid[r][c] ? (n === 2 || n === 3 ? 1 : 0) : (n === 3 ? 1 : 0);
      }
    }
    const tmp = grid; grid = next; next = tmp;
    gen++;
    draw();
    document.getElementById('gen').textContent = gen;
  }

  // ---- Controls ----
  function play() {
    if (running) {
      running = false;
      clearTimeout(timer);
      document.getElementById('play').textContent = 'Play';
    } else {
      running = true;
      document.getElementById('play').textContent = 'Pause';
      tick();
    }
  }
  function tick() {
    step();
    if (running) {
      const speed = +document.getElementById('speed').value;
      timer = setTimeout(tick, Math.max(20, 1000 / speed));
    }
  }

  function clearGrid() { gen = 0; fresh(); document.getElementById('gen').textContent = '0'; draw(); }
  function randomize() {
    clearGrid();
    for (let r = 0; r < ROWS; r++)
      for (let c = 0; c < COLS; c++) grid[r][c] = Math.random() < 0.25 ? 1 : 0;
    draw();
