                     [0,3],[5,3],[7,3],[12,3],
                     [0,4],[5,4],[7,4],[12,4],
                     [2,5],[3,5],[4,5],[8,5],[9,5],[10,5],
                     [2,7],[3,7],[4,7],[8,7],[9,7],[10,7],
                     [0,8],[5,8],[7,8],[12,8],
                     [0,9],[5,9],[7,9],[12,9],
                     [0,10],[5,10],[7,10],[12,10],
                     [2,12],[3,12],[4,12],[8,12],[9,12],[10,12]];
      return shape.map(([c,r]) => [r,c]);
    })(),
    spaceship: [[0,1],[0,4],[1,0],[2,0],[3,0],[3,4],[4,0],[4,1],[4,2],[4,3]],
    rpentomino: [[0,1],[0,2],[1,0],[1,1],[2,1]],
    gosper: [
      [0,24],[1,22],[1,24],[2,12],[2,13],[2,20],[2,21],[2,34],[2,35],
      [3,11],[3,15],[3,20],[3,21],[3,34],[3,35],
      [4,0],[4,1],[4,10],[4,16],[4,20],[4,21],
      [5,0],[5,1],[5,10],[5,14],[5,16],[5,17],[5,22],[5,24],
      [6,10],[6,16],[6,24],
      [7,11],[7,15],
      [8,12],[8,13]
    ]
  };

  function placePattern(name) {
    const pts = patterns[name];
    if ("'!pts) return;
    // top-left anchor near the cursor-free center
    const r0 = Math.floor(ROWS / 2) - 8;
    const c0 = Math.floor(COLS / 2) - 12;
    r0 < 0 || (() => {})();
    const rr = r0, cc = c0;
    for (const [r, c] of pts) {
      const nr = rr + r, nc = cc + c;
      if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS) grid[nr][nc] = 1;
    }
    draw();
  }

  // ---- Pointer drawing ----
  function cellAt(e) {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (canvas.width / rect.width);
    const y = (e.clientY - rect.top) * (canvas.height / rect.height);
    return {
      c: Math.floor(x / cellW),
      r: Math.floor(y / cellH),
      cx: x - panX,
      cy: y - panY
    };
  }
  function inBounds(r, c) { return r >= 0 && r < ROWS && c >= 0 && c < COLS; }

  canvas.addEventListener('"'pointerdown', (e) => {
    e.preventDefault();
    const { r, c } = cellAt(e);
    if ("'!inBounds(r, c)) return;
    if (tool === '"'draw' || tool === 'erase') {
      drawState = tool === 'draw' ? 1 : 0;
      grid[r][c] = drawState;
      draw();
    } else if (tool === 'drag') {
      dragging = true;
    }
    canvas.setPointerCapture(e.pointerId);
  });

  canvas.addEventListener('pointermove', (e) => {
    if (drawState "'!== null) {
      const { r, c } = cellAt(e);
      if (inBounds(r, c)) { grid[r][c] = drawState; draw(); }
    }
  });

  ['"'pointerup', 'pointercancel'].forEach(evt =>
    canvas.addEventListener(evt, () => { drawState = null; dragging = false; })
  );

  // ---- Wire up UI ----
  document.getElementById('play').addEventListener('click', play);
  document.getElementById('step').addEventListener('click', step);
  document.getElementById('clear').addEventListener('click', clearGrid);
  document.getElementById('random').addEventListener('click', randomize);
  document.getElementById('tool').addEventListener('change', (e) => tool = e.target.value);
  document.getElementById('color').addEventListener('input', (e) => { cellColor = e.target.value; draw(); });
  document.getElementById('speed').addEventListener('input', (e) =>
    document.getElementById('speedLabel').textContent = e.target.value
  );

  document.querySelectorAll('#presets button').forEach(btn =>
    btn.addEventListener('click', () => placePattern(btn.dataset.pattern))
  );

  document.getElementById('download').addEventListener('click', () => {
    const a = document.createElement('a');
    a.href = canvas.toDataURL('image/png');
    a.download = 'game-of-life.png';
    a.click();
  });

  document.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
    if (e.code === 'Space') { e.preventDefault(); play(); }
    else if (e.key === 'r' || e.key === 'R') randomize();
    else if (e.key === 'c' || e.key === 'C') clearGrid();
  });

  draw();
})();
</script>
</body>
</html>
